import { ImageResponse } from "next/og";
import { NextResponse } from "next/server";
import { readFile } from "node:fs/promises";
import { join } from "node:path";

// Composes a broadcast-style social post: real photo background, a zoomed
// circular inset, a red BREAKING badge and a condensed red/white headline.
//
// The headline is drawn with real typography (Satori) rather than generated by
// an image model, so the text is always exact and legible. Nano Banana (Gemini
// 2.5 Flash Image) is used only to invent a *background* when the story has no
// photo of its own.

export const runtime = "nodejs";

const NANO_BANANA = "gemini-2.5-flash-image";
const NANO_ENDPOINT = `https://generativelanguage.googleapis.com/v1beta/models/${NANO_BANANA}:generateContent`;

const RATIOS: Record<string, { w: number; h: number }> = {
  "1:1": { w: 1080, h: 1080 },
  "16:9": { w: 1920, h: 1080 },
  "9:16": { w: 1080, h: 1920 },
};

const RED = "#E8232A";

/**
 * The condensed headline font (Anton) is bundled in the repo and read from disk,
 * not fetched from Google Fonts at request time — a runtime fetch is flaky and
 * would 502 the whole generation on a cold start. Cached per process.
 */
let fontData: Buffer | null = null;
async function loadHeadlineFont(): Promise<Buffer> {
  if (!fontData) {
    fontData = await readFile(join(process.cwd(), "src/app/api/generate-post/anton.ttf"));
  }
  return fontData;
}

/** Fetch the publisher photo ourselves so we control UA/timeouts and can embed it. */
async function toDataUri(url: string): Promise<string | null> {
  try {
    const res = await fetch(url, {
      headers: { "user-agent": "Mozilla/5.0 (compatible; NewsPulseBot/0.1)", accept: "image/*" },
      signal: AbortSignal.timeout(12000),
    });
    if (!res.ok) return null;
    const type = res.headers.get("content-type") ?? "image/jpeg";
    if (!type.startsWith("image/")) return null;
    const buf = Buffer.from(await res.arrayBuffer());
    if (buf.byteLength > 6_000_000) return null; // keep the render light
    return `data:${type};base64,${buf.toString("base64")}`;
  } catch {
    return null;
  }
}

/** Only used when a story has no photo: invent a background (never any text). */
async function nanoBananaBackground(title: string, category: string): Promise<string | null> {
  const key = process.env.GEMINI_API_KEY;
  if (!key) return null;
  const prompt =
    "Photographic, editorial news background image, dramatic lighting, shallow depth of field, " +
    "cinematic, high detail. Absolutely no text, no words, no letters, no logos, no watermarks. " +
    `Subject context (${category}): ${title}`;
  try {
    const res = await fetch(NANO_ENDPOINT, {
      method: "POST",
      headers: { "content-type": "application/json", "x-goog-api-key": key },
      body: JSON.stringify({ contents: [{ parts: [{ text: prompt }] }] }),
      signal: AbortSignal.timeout(45000),
    });
    if (!res.ok) return null;
    const data = await res.json();
    const parts = data?.candidates?.[0]?.content?.parts ?? [];
    const img = parts.find((p: { inlineData?: { data?: string } }) => p?.inlineData?.data);
    if (!img) return null;
    return `data:${img.inlineData.mimeType || "image/png"};base64,${img.inlineData.data}`;
  } catch {
    return null;
  }
}

/** Colour the headline in alternating red/white runs, like broadcast lower-thirds. */
function colouredWords(title: string) {
  return title
    .trim()
    .split(/\s+/)
    .map((word, i) => ({ word, red: Math.floor(i / 2) % 2 === 0 }));
}

export async function POST(request: Request) {
  const body = await request.json().catch(() => ({}));
  const { title, category, source, imageUrl, ratio = "1:1" } = body as {
    title?: string;
    category?: string;
    source?: string;
    imageUrl?: string;
    ratio?: string;
  };

  if (!title) return NextResponse.json({ error: "Missing article title." }, { status: 400 });

  const { w: W, h: H } = RATIOS[ratio] ?? RATIOS["1:1"];

  // Background: the real photo first, Nano Banana only as a fallback.
  let bg = imageUrl ? await toDataUri(imageUrl) : null;
  let aiBackground = false;
  if (!bg) {
    bg = await nanoBananaBackground(title, category ?? "News");
    aiBackground = !!bg;
  }

  let font: Buffer;
  try {
    font = await loadHeadlineFont();
  } catch {
    return NextResponse.json(
      { error: "Font unavailable", hint: "The bundled headline font could not be read from disk." },
      { status: 500 },
    );
  }

  const pad = Math.round(W * 0.055);
  const D = Math.round(Math.min(W, H) * 0.3); // circle inset diameter
  const zoom = 2.3; // how far the circle "zooms" into the photo
  const len = title.length;
  const fs = Math.round(W * (len > 140 ? 0.046 : len > 100 ? 0.055 : len > 60 ? 0.068 : 0.082));

  // Built outside the try block: the React Compiler forbids constructing JSX inside try/catch.
  const element = (
        <div
          style={{
            width: W,
            height: H,
            display: "flex",
            position: "relative",
            backgroundColor: "#0b0b0f",
            fontFamily: "Anton",
          }}
        >
          {bg ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img src={bg} alt="" width={W} height={H} style={{ position: "absolute", top: 0, left: 0, width: W, height: H, objectFit: "cover" }} />
          ) : (
            <div style={{ position: "absolute", top: 0, left: 0, width: W, height: H, display: "flex", background: "linear-gradient(135deg, #5b21b6, #9333ea 55%, #db2777)" }} />
          )}

          {/* legibility scrim */}
          <div
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              bottom: 0,
              height: Math.round(H * 0.62),
              display: "flex",
              background: "linear-gradient(to top, rgba(0,0,0,0.94) 30%, rgba(0,0,0,0.55) 62%, rgba(0,0,0,0))",
            }}
          />

          {/* zoomed circular inset — shows more detail of the same photo */}
          {bg ? (
            // A background-image circle clips cleanly in Satori; a nested <img>
            // leaves square corners because border-radius does not mask it.
            <div
              style={{
                position: "absolute",
                top: pad,
                left: pad,
                width: D,
                height: D,
                borderRadius: "50%",
                border: `${Math.round(D * 0.045)}px solid #ffffff`,
                display: "flex",
                backgroundImage: `url(${bg})`,
                backgroundSize: `${Math.round(D * zoom)}px ${Math.round(D * zoom)}px`,
                backgroundPosition: "center",
                backgroundRepeat: "no-repeat",
              }}
            />
          ) : null}

          {/* headline block */}
          <div style={{ position: "absolute", left: pad, right: pad, bottom: pad, display: "flex", flexDirection: "column" }}>
            <div style={{ display: "flex", alignItems: "center", marginBottom: Math.round(fs * 0.28) }}>
              <div
                style={{
                  display: "flex",
                  backgroundColor: RED,
                  color: "#fff",
                  fontSize: Math.round(fs * 0.42),
                  letterSpacing: Math.round(fs * 0.05),
                  padding: `${Math.round(fs * 0.1)}px ${Math.round(fs * 0.3)}px`,
                  textTransform: "uppercase",
                }}
              >
                Breaking
              </div>
              <div style={{ display: "flex", flex: 1, height: Math.round(fs * 0.06), backgroundColor: RED, marginLeft: Math.round(fs * 0.25) }} />
            </div>

            <div style={{ display: "flex", flexWrap: "wrap", width: W - pad * 2 }}>
              {colouredWords(title).map(({ word, red }, i) => (
                <div
                  key={i}
                  style={{
                    display: "flex",
                    color: red ? RED : "#ffffff",
                    fontSize: fs,
                    lineHeight: 1.02,
                    textTransform: "uppercase",
                    marginRight: Math.round(fs * 0.22),
                    marginBottom: Math.round(fs * 0.06),
                  }}
                >
                  {word}
                </div>
              ))}
            </div>

            <div
              style={{
                display: "flex",
                marginTop: Math.round(fs * 0.32),
                color: "rgba(255,255,255,0.72)",
                fontSize: Math.round(fs * 0.3),
                letterSpacing: Math.round(fs * 0.03),
                textTransform: "uppercase",
              }}
            >
              {[source, category, aiBackground ? "AI background" : null].filter(Boolean).join("  •  ")}
            </div>
          </div>
        </div>
  );

  try {
    const image = new ImageResponse(element, {
      width: W,
      height: H,
      fonts: [{ name: "Anton", data: font, weight: 400, style: "normal" }],
    });

    const buf = Buffer.from(await image.arrayBuffer());
    return NextResponse.json({
      image: `data:image/png;base64,${buf.toString("base64")}`,
      ratio,
      aiBackground,
      usedPhoto: !!imageUrl && !aiBackground,
    });
  } catch (e) {
    return NextResponse.json(
      { error: "Generation failed", hint: e instanceof Error ? e.message.slice(0, 200) : "Unknown render error." },
      { status: 500 },
    );
  }
}
